package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;

import java.time.LocalDate;
import java.time.Month;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.temporal.ChronoUnit;
import java.util.Locale;

/**
 * PAYMENT CALENDAR
 * Rewritten for Java 21, thread-safe, Warsaw bank time.
 */
public class LegacyPaymentCalendar implements PaymentCalendar {

    private static final ZoneId BANK_ZONE = ZoneId.of("Europe/Warsaw");
    private static final java.time.format.DateTimeFormatter DAY_IN =
            java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd");
    private static final java.time.format.DateTimeFormatter INSTANT_IN =
            java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ssXXX");

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate localDate = LocalDate.parse(date, DAY_IN);
        int dayOfWeek = localDate.getDayOfWeek().getValue(); // 1=Mon .. 7=Sun
        if (dayOfWeek >= 6) {
            return false;
        }
        if (isHoliday(localDate)) {
            return false;
        }
        return true;
    }

    private static boolean isHoliday(LocalDate date) {
        int month = date.getMonthValue();
        int day = date.getDayOfMonth();
        return (month == 1 && day == 1) ||      // 1 Jan
               (month == 1 && day == 6) ||      // 6 Jan (Epiphany)
               (month == 5 && day == 1) ||      // 1 May
               (month == 5 && day == 3) ||      // 3 May
               (month == 8 && day == 15) ||     // 15 Aug
               (month == 11 && day == 1) ||     // 1 Nov
               (month == 11 && day == 11) ||    // 11 Nov
               (month == 12 && day == 25) ||    // 25 Dec
               (month == 12 && day == 26);      // 26 Dec
    }

    @Override
    public String processingDate(String submittedAt) {
        OffsetDateTime odt = OffsetDateTime.parse(submittedAt, INSTANT_IN);
        ZonedDateTime zdt = odt.withZoneSameInstant(BANK_ZONE);
        LocalDate localDate = zdt.toLocalDate();
        LocalTime time = zdt.toLocalTime();

        boolean inTime = time.compareTo(LocalTime.MIDNIGHT.plusHours(16)) <= 0;
        boolean isBday = isBusinessDay(localDate.toString());

        if (isBday && inTime) {
            return localDate.format(DAY_IN);
        }
        return nextBusinessDay(localDate).format(DAY_IN);
    }

    private static LocalDate nextBusinessDay(LocalDate from) {
        LocalDate next = from.plusDays(1);
        while (!isBusinessDay(next)) {
            next = next.plusDays(1);
        }
        return next;
    }

    @Override
    public String settlementDate(String submittedAt) {
        String processing = processingDate(submittedAt);
        LocalDate procDate = LocalDate.parse(processing, DAY_IN);
        return nextBusinessDay(procDate).format(DAY_IN);
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = LocalDate.parse(dueDate, DAY_IN);
        OffsetDateTime paidOdt = OffsetDateTime.parse(paidAt, INSTANT_IN);
        ZonedDateTime paidZdt = paidOdt.withZoneSameInstant(BANK_ZONE);
        LocalDate paid = paidZdt.toLocalDate();

        long days = ChronoUnit.DAYS.between(due, paid);
        return (days < 0) ? 0 : (int) days;
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate localDate = LocalDate.parse(date, DAY_IN);
        int originalDay = localDate.getDayOfMonth();
        boolean originalWasMonthEnd = (originalDay == localDate.lengthOfMonth());

        LocalDate target = localDate.plusMonths(months);

        if (originalWasMonthEnd) {
            target = target.withDayOfMonth(target.lengthOfMonth());
        } else {
            if (originalDay > target.lengthOfMonth()) {
                target = target.withDayOfMonth(target.lengthOfMonth());
            } else {
                target = target.withDayOfMonth(originalDay);
            }
        }

        return target.format(DAY_IN);
    }
}

