    private static boolean isHoliday(LocalDate date) {
        int month = date.getMonthValue();
        int day = date.getDayOfMonth();
        return (month == 1 && day == 1) ||      // 1 Jan
               (month == 1 && day == 6) ||      // 6 Jan (Epiphany)
               (month == 5 && day == 1) ||      // 1 May
               (month == 5 && day == 3) ||      // 3 May
               (month == 8 && day == 15) ||     // 15 Aug
               (month == 11 && day == 1) ||     // 1 Nov
               (month == 11 && day == 11) ||    // 11 Nov
               (month == 12 && day == 25) ||    // 25 Dec
               (month == 12 && day == 26);      // 26 Dec
    }

    @Override
    public String processingDate(String submittedAt) {
        OffsetDateTime odt = OffsetDateTime.parse(submittedAt, INSTANT_IN);
        ZonedDateTime zdt = odt.withZoneSameInstant(BANK_ZONE);
        LocalDate localDate = zdt.toLocalDate();
        LocalTime time = zdt.toLocalTime();

        boolean inTime = time.compareTo(LocalTime.MIDNIGHT.plusHours(16)) <= 0;
        boolean isBday = isBusinessDay(localDate.toString());

        if (isBday && inTime) {
            return localDate.format(DAY_IN);
        }
        return nextBusinessDay(localDate).format(DAY_IN);
    }

    private static LocalDate nextBusinessDay(LocalDate from) {
        LocalDate next = from.plusDays(1);
        while (!isBusinessDay(next)) {
            next = next.plusDays(1);
        }
        return next;
    }

    @Override
    public String settlementDate(String submittedAt) {
        String processing = processingDate(submittedAt);
        LocalDate procDate = LocalDate.parse(processing, DAY_IN);
        return nextBusinessDay(procDate).format(DAY_IN);
