            ZonedDateTime paidWarsaw = paidInstant.atZone(BANK_ZONE);

            LocalDate dueDate = dueWarsaw.toLocalDate();
            LocalDate paidDate = paidWarsaw.toLocalDate();

            if (paidDate.isBefore(dueDate) || paidDate.isEqual(dueDate)) {
                return 0;
            }
            return (int) ChronoUnit.DAYS.between(dueDate, paidDate);
        } catch (Exception e) {
            throw new IllegalArgumentException();
        }
    }

    @Override
    public String addMonths(String date, int months) {
        try {
            LocalDate local = LocalDate.parse(date);
            local = local.plusMonths(months);
            // Day-of-month clamping - if the day is invalid for the new month, clamp to last day
            int day = local.getDayOfMonth();
            int maxDay = local.lengthOfMonth();
            if (day > maxDay) {
                local = local.withDayOfMonth(maxDay);
            }
            return local.toString();
        } catch (Exception e) {
            throw new IllegalArgumentException();
        }
    }
